// Render grid, triangle and cirle

vec3 Grid(in vec2 uv)
{
    vec3 color = vec3(0.0);
    vec2 cell = 1. - 2. * abs(fract(uv) - 0.5); //(0, 1) -> (-0.5, 0.5) -> (0, 0.5) -> (0, 1) -> (1, 0)

    if (abs(uv.x) < 2. * fwidth(uv.x)) 
    {
        color.r = 1.0;
    } 
    else if (abs(uv.y) < 2. * fwidth(uv.y))
    {
        color.g = 1.0;
    }
    else 
    {
        if (cell.x < 2. * fwidth(uv.x) || cell.y < 2.*fwidth(uv.y)) 
            color = vec3(1.0);
    }
    return 0.2 * color;
}

float Cross2(vec2 p1, vec2 p2, vec2 p3)
{
    // p1p2 X p1p3
    return (p2.x - p1.x) * (p3.y - p1.y) - (p3.x - p1.x) * (p2.y - p1.y);
}

bool Segment(vec2 uv, vec2 start, vec2 end, float width)
{
    /* when the 3 points (fragCoord,start, end) on the line:
     * (start, uv) X (start, end) = |(start, uv)| * |(start, end)| * sin(s) = 0
    */
    if ( uv.x - min(start.x, end.x) < -width || 
         uv.x - max(start.x, end.x) > width || 
         uv.y - min(start.y, end.y) < -width || 
         uv.y - max(start.y, end.y) > width ) {
            return false;
        }

    float cross_val = Cross2(start, end, uv);
    if (abs(cross_val) <= width) {
        return true;
    }
    return false;
}

bool Segment2(vec2 p, vec2 a, vec2 b, float w)
{
    vec2 ba = b - a;
    vec2 pa = p - a;

    float proj = clamp(dot(pa, ba)/dot(ba, ba), 0., 1.);
    float d = length(proj * ba - pa);
    if (d <= w)
        return true;
    return false;
}

bool Triangle(in vec2 uv, vec2 a, vec2 b, vec2 c, float w)
{
    return Segment2(uv, a, b, w) || Segment2(uv, a, c, w) || Segment2(uv, b, c, w);
}
void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 uv = 3.*(2.0 * fragCoord - iResolution.xy) / min(iResolution.x, iResolution.y);
    vec3 color = Grid(uv);
    // triangle
    float width = 0.01;//1.5 * fwidth(uv.x);
    bool on_triangle = Triangle(uv, vec2(-1.), vec2(1., -1.), vec2(0, 1.), width);
    // color = mix(color, vec3(1., 1., 0.), on_triangle ? 1.0 : 0.);
    if (on_triangle) {
        color = vec3(1., 1., 0.);
    }

    // circle
    float radius = 1.5;
    vec2 center = vec2(0.1, 0.15);
    float dist = length(uv-center);
    if ( abs(dist - radius) < width) {
        color = mix(color, vec3(0., 0., 1.), 1.);
    }

    fragColor = vec4(color, 1.0);
}
